const crypto = require('crypto');
async function testUpload() {
    const cloudName = 'mvhjuh83';
    const apiKey = '636819913243949';
    const apiSecret = 'Klov4BCszxgMpPmr_PUD9GFvgJw';
    
    const timestamp = Math.round((new Date).getTime() / 1000);
    const strToSign = 'timestamp=' + timestamp + apiSecret;
    const signature = crypto.createHash('sha1').update(strToSign).digest('hex');

    const formData = new FormData();
    // Tiny valid video data (1x1 MP4) in base64
    const videoData = 'data:video/mp4;base64,';
    formData.append('file', videoData);
    formData.append('api_key', apiKey);
    formData.append('timestamp', timestamp);
    formData.append('signature', signature);

    const res = await fetch('https://api.cloudinary.com/v1_1/' + cloudName + '/auto/upload', {
        method: 'POST',
        body: formData
    });
    
    console.log("Status:", res.status);
    console.log("Response:", await res.text());
}
testUpload();
